def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    cells={(r,c) for r in range(h) for c in range(w) if g[r][c]==2}
    comps=[]
    while cells:
        stack=[cells.pop()]; comp=[]
        while stack:
            r,c=stack.pop(); comp.append((r,c))
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in cells: cells.remove(q); stack.append(q)
        comps.append(comp)
    if len(comps)==2:
        a,b=sorted(comps,key=lambda x:min(r for r,c in x))
        ra=max(r for r,c in a); rb=min(r for r,c in b)
        line=(ra+rb)//2
        for c in range(w): g[line][c]=3
    return g
